// IEEE 1364 Verilog 4-to-1 Multiplexer and 4-Bit Priority Encoder
module mux4_priority (
  input  [7:0] d0,
  input  [7:0] d1,
  input  [7:0] d2,
  input  [7:0] d3,
  input  [3:0] req,
  output reg [7:0] y_out,
  output reg [1:0] sel_code,
  output wire valid
);
  assign valid = req[3] | req[2] | req[1] | req[0];

  always @(*) begin
    if (req[3])
      sel_code = 2'b11;
    else if (req[2])
      sel_code = 2'b10;
    else if (req[1])
      sel_code = 2'b01;
    else
      sel_code = 2'b00;
  end

  always @(*) begin
    case (sel_code)
      2'b00: y_out = d0;
      2'b01: y_out = d1;
      2'b10: y_out = d2;
      2'b11: y_out = d3;
      default: y_out = 8'h00;
    endcase
  end
endmodule

// 4x8-Bit Synchronous FIFO Ring Buffer
module sync_fifo (
  input        clk,
  input        rst,
  input        wr_en,
  input        rd_en,
  input  [7:0] din,
  output reg [7:0] dout,
  output wire  full,
  output wire  empty
);
  reg [7:0] slot0;
  reg [7:0] slot1;
  reg [7:0] slot2;
  reg [7:0] slot3;
  reg [1:0] wr_ptr;
  reg [1:0] rd_ptr;
  reg [2:0] count;

  assign full  = (count == 3'd4);
  assign empty = (count == 3'd0);

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 2'd0;
      rd_ptr <= 2'd0;
      count  <= 3'd0;
      dout   <= 8'h00;
      slot0  <= 8'h00;
      slot1  <= 8'h00;
      slot2  <= 8'h00;
      slot3  <= 8'h00;
    end else begin
      if (wr_en && !full) begin
        case (wr_ptr)
          2'd0: slot0 <= din;
          2'd1: slot1 <= din;
          2'd2: slot2 <= din;
          2'd3: slot3 <= din;
          default: slot0 <= din;
        endcase
        wr_ptr <= wr_ptr + 2'd1;
      end

      if (rd_en && !empty) begin
        case (rd_ptr)
          2'd0: dout <= slot0;
          2'd1: dout <= slot1;
          2'd2: dout <= slot2;
          2'd3: dout <= slot3;
          default: dout <= slot0;
        endcase
        rd_ptr <= rd_ptr + 2'd1;
      end

      if (wr_en && !full && !(rd_en && !empty))
        count <= count + 3'd1;
      else if (rd_en && !empty && !(wr_en && !full))
        count <= count - 3'd1;
    end
  end
endmodule

// Mode-0 8-Bit SPI Master Controller FSM
module spi_master (
  input        clk,
  input        rst,
  input        start,
  input  [7:0] tx_data,
  input        miso,
  output reg   sclk,
  output reg   mosi,
  output reg   cs_n,
  output reg [7:0] rx_data,
  output reg   done
);
  localparam S_IDLE  = 2'b00;
  localparam S_LOAD  = 2'b01;
  localparam S_SHIFT = 2'b10;
  localparam S_DONE  = 2'b11;

  reg [1:0] state;
  reg [7:0] tx_shift;
  reg [7:0] rx_shift;
  reg [2:0] bit_cnt;

  always @(posedge clk) begin
    if (rst) begin
      state    <= S_IDLE;
      sclk     <= 1'b0;
      mosi     <= 1'b0;
      cs_n     <= 1'b1;
      tx_shift <= 8'h00;
      rx_shift <= 8'h00;
      rx_data  <= 8'h00;
      bit_cnt  <= 3'd0;
      done     <= 1'b0;
    end else begin
      done <= 1'b0;
      case (state)
        S_IDLE: begin
          cs_n <= 1'b1;
          sclk <= 1'b0;
          if (start) begin
            tx_shift <= tx_data;
            bit_cnt  <= 3'd7;
            cs_n     <= 1'b0;
            state    <= S_LOAD;
          end
        end
        S_LOAD: begin
          mosi  <= tx_shift[7];
          sclk  <= 1'b0;
          state <= S_SHIFT;
        end
        S_SHIFT: begin
          sclk     <= 1'b1;
          rx_shift <= {rx_shift[6:0], miso};
          tx_shift <= {tx_shift[6:0], 1'b0};
          if (bit_cnt == 3'd0) begin
            state <= S_DONE;
          end else begin
            bit_cnt <= bit_cnt - 3'd1;
            state   <= S_LOAD;
          end
        end
        S_DONE: begin
          sclk    <= 1'b0;
          cs_n    <= 1'b1;
          rx_data <= rx_shift;
          done    <= 1'b1;
          state   <= S_IDLE;
        end
        default: state <= S_IDLE;
      endcase
    end
  end
endmodule

// Parameterized Complementary PWM Motor Driver with Dead-Time Control
module pwm_driver #(
  parameter PERIOD = 8'd200,
  parameter DEADTIME = 8'd4
) (
  input        clk,
  input        rst,
  input        enable,
  input  [7:0] duty,
  output reg   pwm_hi,
  output reg   pwm_lo
);
  reg [7:0] counter;

  always @(posedge clk) begin
    if (rst) begin
      counter <= 8'd0;
      pwm_hi  <= 1'b0;
      pwm_lo  <= 1'b0;
    end else if (!enable) begin
      counter <= 8'd0;
      pwm_hi  <= 1'b0;
      pwm_lo  <= 1'b0;
    end else begin
      if (counter >= PERIOD)
        counter <= 8'd0;
      else
        counter <= counter + 8'd1;

      if (counter < duty) begin
        pwm_hi <= 1'b1;
        pwm_lo <= 1'b0;
      end else if (counter >= duty + DEADTIME) begin
        pwm_hi <= 1'b0;
        pwm_lo <= 1'b1;
      end else begin
        pwm_hi <= 1'b0;
        pwm_lo <= 1'b0;
      end
    end
  end
endmodule

